const icons={home:'⌂',orders:'▣',listings:'☰',earnings:'₱',profile:'◯',search:'⌕',arrow:'→',plus:'+'};
const esc=s=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const state={page:'dashboard',role:'Owner',orderFilter:'All',query:'',orderView:'list',detail:null,listing:null,toast:''};
const listings=[
 {id:'cake',name:'Whole Sans Rival Cake',category:'Bakery',price:'₱1,200',unit:'per item',stock:'12 available',status:'Active',location:'Pick-up at shop',payment:'Room charge + Gateway'},
 {id:'box',name:'Island Breakfast Box',category:'Food',price:'₱680',unit:'per item',stock:'24 available',status:'Active',location:'Delivery to room',payment:'Room charge + Gateway'},
 {id:'coffee',name:'Cold Brew Bottle',category:'Drinks',price:'₱220',unit:'per item',stock:'Paused',status:'Paused',location:'Pick-up at shop',payment:'Gateway only'}
];
const orders=[
 {id:'ORD-1042',kind:'In-app order',guest:'John D.',hotel:'Luna Bay Resort',room:'101',item:'Whole Sans Rival Cake',quantity:'1 ×',when:'Oct 2 · 3:00 PM',fulfilment:'Pick-up at shop',total:'₱1,200',payment:'Charged to room',settlement:'Posted to room',status:'Confirmed',timeline:[['Order placed','Sep 29 · 8:14 AM'],['Automatically confirmed','Sep 29 · 8:14 AM']],notes:'Please write “Happy Anniversary” on the box.',contact:'Open guest chat'},
 {id:'CB-8821',kind:'Booking',guest:'Amelia Reyes',hotel:'Luna Bay Resort',room:'508',item:'Private bakery tasting',quantity:'2 guests',when:'Today · 5:30 PM',fulfilment:'Tasting room',total:'₱2,400',payment:'Paid via gateway',settlement:'Paid by guest',status:'Pending',timeline:[['Booking requested','Sep 29 · 9:02 AM']],notes:'Window seat if available.',contact:'Open guest chat'},
 {id:'CT-2208',kind:'Counter charge',guest:'Maya Tan',hotel:'Luna Bay Resort',room:'314',item:'Coffee and pastry set',quantity:'2 ×',when:'Today · 10:15 AM',fulfilment:'Counter',total:'₱540',payment:'Charged to room',settlement:'Posted to room',status:'Posted to room',timeline:[['Posted by validator app','Sep 29 · 10:15 AM']],notes:'Read-only record. Voids happen in the validator app.',contact:'View record'},
 {id:'ORD-1037',kind:'In-app order',guest:'Oliver Brown',hotel:'Luna Bay Resort',room:'205',item:'Island Breakfast Box',quantity:'2 ×',when:'Today · 8:00 AM',fulfilment:'Delivery to room',total:'₱1,360',payment:'Paid via gateway',settlement:'In payout',status:'Completed',timeline:[['Order placed','Sep 28 · 6:40 PM'],['Completed','Sep 29 · 8:32 AM']],notes:'No nuts, please.',contact:'Open guest chat'},
 {id:'CB-8812',kind:'Booking',guest:'Priya Shah',hotel:'Luna Bay Resort',room:'412',item:'Chef’s counter experience',quantity:'4 guests',when:'Sep 28 · 7:00 PM',fulfilment:'Chef’s counter',total:'₱8,800',payment:'Charged to room',settlement:'Guest checked out',status:'Completed',timeline:[['Booking confirmed','Sep 25 · 11:20 AM'],['Completed','Sep 28 · 9:10 PM'],['Guest checked out','Sep 29 · 11:04 AM']],notes:'',contact:'View guest record'}
];
const nav=(id,label,icon)=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}"><span class="nav-icon">${icons[icon]}</span><span>${label}</span>${id==='orders'?'<b class="nav-badge">2</b>':''}</button>`;
function shell(content){return `<aside class="sidebar"><div class="brand"><span class="brand-mark">C</span>Cabana</div><button class="outlet-button"><span class="outlet-avatar">SB</span><span><strong>Sans Rival Bakehouse</strong><small>Bakery · Live</small></span><span>⌄</span></button><nav class="nav-list">${nav('dashboard','Dashboard','home')}${nav('orders','Orders','orders')}${nav('listings','Listings','listings')}${state.role==='Owner'?nav('earnings','Earnings','earnings'):''}${nav('profile','Profile','profile')}</nav><div class="sidebar-bottom"><div class="partner-mini"><strong>${state.role}</strong><span>Portal access</span></div></div></aside><div class="main-wrap"><header class="topbar"><div class="topbar-context"><span class="kicker">Sans Rival Bakehouse</span><span class="slash">/</span><strong>${state.page==='listings'?'Listings':state.page[0].toUpperCase()+state.page.slice(1)}</strong></div><div class="top-actions"><span class="role-pill">${state.role}</span><button class="outlet-button compact"><span class="outlet-avatar">SB</span><span>Sans Rival Bakehouse</span></button></div></header><main class="page">${content}</main><nav class="mobile-nav">${nav('dashboard','Dashboard','home')}${nav('orders','Orders','orders')}${nav('listings','Listings','listings')}${state.role==='Owner'?nav('earnings','Earnings','earnings'):''}${nav('profile','Profile','profile')}</nav></div>`}
function head(title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">SANS RIVAL BAKEHOUSE</div><h1>${title}</h1><p class="subtext">${sub}</p></div>${action}</div>`}
function dashboard(){return `${head('Good morning, Leah',`Monday, September 29 · Here's what needs your attention today.`)}<section class="kpi-grid"><div class="kpi-card"><span>Today’s orders</span><strong>8</strong><small>2 need confirmation</small></div><div class="kpi-card"><span>Today’s revenue</span><strong>₱6,420</strong><small>6 completed or active</small></div><div class="kpi-card"><span>Room charges today</span><strong>₱3,860</strong><small>Posted to guest rooms</small></div><div class="kpi-card"><span>Next payout</span><strong>₱42,180</strong><small>Friday, Oct 2</small></div></section><div class="dashboard-columns"><div class="dashboard-main"><section class="card split-card"><div class="card-header"><div><h2>Revenue overview</h2><span class="count">September 23–29</span></div><button class="button ghost" data-page="earnings">View earnings ${icons.arrow}</button></div><div class="split-content"><div class="split-total"><strong>₱84,260</strong><span>This week</span><div class="split-bar"><i style="width:62%"></i><i style="width:38%"></i></div><div class="legend"><span><i class="room-dot"></i>Room charge ₱52,240</span><span><i class="gateway-dot"></i>Gateway ₱32,020</span></div></div><div class="mini-chart">${[42,58,47,72,63,88,76].map((n,i)=>`<div class="chart-col"><div class="chart-bar" style="height:${n}px"></div><small>${['23','24','25','26','27','28','29'][i]}</small></div>`).join('')}</div></div></section><section class="card"><div class="card-header"><div><h2>Upcoming</h2><span class="count">Next 5 orders and bookings</span></div><button class="button ghost" data-page="orders">View all ${icons.arrow}</button></div><div class="upcoming-list">${orders.filter(o=>['Pending','Confirmed'].includes(o.status)).slice(0,5).map(o=>`<button class="upcoming-row" data-detail="${o.id}"><span class="upcoming-time">${o.when}</span><span class="upcoming-main"><strong>${esc(o.guest)} <em>Room ${esc(o.room)}</em></strong><small>${esc(o.item)} · ${esc(o.quantity)}</small></span><span class="payment-badge ${o.payment.includes('room')?'room':'gateway'}">${o.payment}</span>${icons.arrow}</button>`).join('')}</div></section></div><div class="dashboard-side"><section class="card"><div class="card-header"><h2>Alerts</h2><span class="count">3 items</span></div><div class="alert-list"><button class="alert-row" data-page="orders"><span class="alert-icon warning">!</span><span><strong>2 orders await confirmation</strong><small>One booking · one in-app order</small></span>${icons.arrow}</button><button class="alert-row"><span class="alert-icon success">✓</span><span><strong>Payout sent</strong><small>₱38,420 · Sep 26</small></span>${icons.arrow}</button><button class="alert-row"><span class="alert-icon warning">!</span><span><strong>Refund request</strong><small>ORD-1028 · Review by Oct 1</small></span>${icons.arrow}</button></div></section><section class="card"><div class="card-header"><h2>Top listings</h2><span class="count">This month</span></div><div class="ranking">${[['Whole Sans Rival Cake','42 orders','₱50,400'],['Island Breakfast Box','28 orders','₱19,040'],['Cold Brew Bottle','18 orders','₱3,960']].map((x,i)=>`<div class="rank-row"><b>${i+1}</b><span><strong>${x[0]}</strong><small>${x[1]}</small></span><strong>${x[2]}</strong></div>`).join('')}</div></section></div></div>`}
function filterChips(){return `<div class="filter-scroll">${['All','Bookings','In-app orders','Counter','Room charge','Paid','Pending','Completed','Cancelled'].map(x=>`<button class="filter ${state.orderFilter===x?'active':''}" data-order-filter="${x}">${x}</button>`).join('')}</div>`}
function ordersView(){const filtered=orders.filter(o=>(!state.query||`${o.guest} ${o.room} ${o.item}`.toLowerCase().includes(state.query.toLowerCase()))&&(state.orderFilter==='All'||state.orderFilter===o.kind||state.orderFilter===o.status||state.orderFilter==='Room charge'&&o.payment==='Charged to room'||state.orderFilter==='Paid'&&o.payment==='Paid via gateway'));return `${head('Orders','Bookings, in-app orders, and counter charges in one operational queue.',`<button class="button primary" data-toast="Block date controls opened">${icons.plus} Block availability</button>`)}<div class="orders-toolbar"><label class="search-box">${icons.search}<input value="${esc(state.query)}" data-search placeholder="Search guest or room number" /></label><div class="view-toggle"><button class="${state.orderView==='list'?'active':''}" data-view="list">List</button><button class="${state.orderView==='calendar'?'active':''}" data-view="calendar">Calendar</button></div></div>${filterChips()}${state.orderView==='calendar'?calendarOrders():`<section class="order-list">${filtered.length?filtered.map(orderCard).join(''):`<div class="empty-state"><strong>No matching orders</strong><span>Try another guest name, room, or status.</span></div>`}</section>`}`}
function orderCard(o){return `<button class="order-card" data-detail="${o.id}"><div class="order-card-top"><div><span class="type-badge ${o.kind.toLowerCase().replaceAll(' ','-')}">${o.kind}</span><strong>${esc(o.guest)} <small>Room ${esc(o.room)}</small></strong></div><span class="status ${o.status.toLowerCase().replaceAll(' ','-')}">${o.status}</span></div><div class="order-card-body"><div><span class="order-item">${esc(o.item)}</span><small>${esc(o.quantity)} · ${esc(o.when)}</small></div><div><span class="payment-badge ${o.payment.includes('room')?'room':'gateway'}">${o.payment}</span><strong class="order-total">${o.total}</strong></div></div><div class="order-card-foot"><span>${o.hotel} · ${o.fulfilment}</span><span>${icons.arrow}</span></div></button>`}
function calendarOrders(){return `<section class="card calendar-card"><div class="card-header"><div><h2>October 2026</h2><span class="count">Monday, Sep 28 – Sunday, Oct 4</span></div><div class="calendar-controls"><button class="button small">Day</button><button class="button small active">Week</button><button class="button small">Month</button></div></div><div class="calendar-capacity"><span>Today’s capacity</span><strong>3 of 12 bakery slots booked</strong><button class="button small" data-toast="Availability blocker opened">Block date or unit</button></div><div class="schedule-grid">${['Mon 28','Tue 29','Wed 30','Thu 1','Fri 2','Sat 3','Sun 4'].map((d,i)=>`<div class="schedule-day"><strong>${d}</strong>${i===1?`<button data-detail="CT-2208"><b>10:15</b> Counter charge</button>`:''}${i===3?`<button data-detail="ORD-1042"><b>3:00 PM</b> Cake pick-up</button>`:''}${i===4?`<button data-detail="CB-8821"><b>5:30 PM</b> Tasting booking</button>`:''}</div>`).join('')}</div></section>`}
function orderDetail(){const o=orders.find(x=>x.id===state.detail);if(!o)return ordersView();const counter=o.kind==='Counter charge';return `<button class="back" data-page="orders">← Back to orders</button><div class="detail-panel"><div class="detail-main"><section class="card detail-card"><div class="detail-title"><div><div class="section-label">${o.kind} · ${o.id}</div><h1>${esc(o.item)}</h1><p class="subtext">${esc(o.guest)} · ${o.hotel} · Room ${o.room}</p></div><span class="status ${o.status.toLowerCase().replaceAll(' ','-')}">${o.status}</span></div><div class="detail-meta"><div class="meta-item"><label>Guest</label><strong>${esc(o.guest)} · Room ${esc(o.room)}</strong></div><div class="meta-item"><label>Date / time</label><strong>${o.when}</strong></div><div class="meta-item"><label>Fulfilment</label><strong>${o.fulfilment}</strong></div><div class="meta-item"><label>Payment</label><strong>${o.payment}</strong></div><div class="meta-item"><label>Settlement</label><strong>${o.settlement}</strong></div><div class="meta-item"><label>Total</label><strong>${o.total}</strong></div></div><div class="detail-contact"><button class="button small" data-toast="${o.contact}">${o.contact}</button><span>Guest details shown only for fulfilment.</span></div></section><section class="card detail-card"><div class="section-label">Items and notes</div><div class="line-item"><span>${esc(o.item)} <small>${esc(o.quantity)}</small></span><strong>${o.total}</strong></div><div class="price-breakdown"><span>Unit price × quantity</span><strong>${o.total}</strong><span>Add-ons</span><strong>₱0</strong><span class="total-line">Total</span><strong class="total-line">${o.total}</strong></div><div class="info-block"><strong>Guest notes</strong><p>${esc(o.notes||'No special notes.')}</p></div></section></div><aside class="detail-side"><section class="card side-action"><h3>${counter?'Record status':'Next action'}</h3>${counter?`<div class="notice">Counter charges are read-only here. Voids happen in the separate validator app.</div>`:`<div class="action-stack">${o.status==='Pending'?`<button class="button primary" data-action="confirm">Confirm</button><button class="button" data-action="reschedule">Reschedule</button><button class="button danger" data-action="cancel">Decline / cancel</button>`:o.status==='Confirmed'?`<button class="button primary" data-action="preparing">Mark preparing</button><button class="button" data-action="inuse">Mark in use</button><button class="button danger" data-action="cancel">Cancel</button>`:o.status==='Preparing'?`<button class="button primary" data-action="ready">Mark ready · notify guest</button><button class="button danger" data-action="cancel">Cancel</button>`:o.status==='Ready'?`<button class="button primary" data-action="complete">Mark completed</button>`:`<span class="completion-note">No further vendor action is needed.</span>`}</div>`}</section><section class="card side-action"><h3>Status timeline</h3><div class="timeline">${o.timeline.map((t,i)=>`<div class="timeline-row"><span class="timeline-dot"></span><div><strong>${t[0]}</strong><span>${t[1]}</span></div></div>`).join('')}</div></section></aside></div>`}
function listingsView(){return `${head('Listings','Manage what guests can book or buy, at your own prices.',`<button class="button primary" data-listing-new>${icons.plus} Add listing</button>`)}<div class="listing-toolbar"><div class="listing-summary"><strong>${listings.filter(x=>x.status==='Active').length} active listings</strong><span>Visible to guests of Luna Bay Resort</span></div><button class="button" data-toast="Availability settings opened">Availability settings</button></div><div class="listing-grid">${listings.map(l=>`<article class="listing-card"><div class="listing-photo">${l.category==='Bakery'?'CAKE':l.category==='Food'?'BOX':'COFFEE'}</div><div class="listing-content"><div class="listing-heading"><div><span class="section-label">${l.category}</span><h2>${l.name}</h2></div><span class="status ${l.status.toLowerCase()}">${l.status}</span></div><div class="listing-price"><strong>${l.price}</strong><span>${l.unit}</span></div><div class="listing-details"><span>${l.stock}</span><span>${l.location}</span><span>${l.payment}</span></div><div class="listing-actions"><button class="button small" data-toast="${l.name} editor opened">Edit</button><button class="toggle ${l.status==='Active'?'on':''}" aria-label="Toggle ${l.name}"></button></div></div></article>`).join('')}</div><section class="card listing-rules"><div class="card-header"><div><h2>Booking and payment rules</h2><span class="count">Applied to new guest requests</span></div><button class="button small" data-toast="Rules editor opened">Edit</button></div><div class="rules-grid"><div><strong>Payment options</strong><span>Charge to room · Pay now via gateway</span></div><div><strong>Cancellation policy</strong><span>Moderate · Refund amount shown before cancel</span></div><div><strong>Pre-arrival booking</strong><span>Allowed · Gateway payment only before check-in</span></div><div><strong>Operating hours</strong><span>Daily · 7:00 AM–9:00 PM</span></div></div></section>`}
function earningsView(){if(state.role!=='Owner')return `<div class="empty-state large"><strong>Earnings is owner-only</strong><span>Ask an owner to review payout and settlement details.</span></div>`;return `${head('Earnings','What Cabana owes Sans Rival Bakehouse and when it arrives.',`<button class="button" data-toast="Statement export prepared">Export statement</button>`)}<div class="earnings-kpis"><div class="kpi-card"><span>Pending settlement</span><strong>₱26,840</strong><small>Room charges posted</small></div><div class="kpi-card"><span>Next payout</span><strong>₱42,180</strong><small>Friday, Oct 2</small></div><div class="kpi-card"><span>Paid this month</span><strong>₱118,420</strong><small>3 weekly payouts</small></div></div><div class="tabs"><button class="active">Transactions</button><button>Payouts</button><button>Refunds <b>1</b></button></div><section class="card data-card"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Guest / item</th><th>Method</th><th>Gross</th><th>Commission</th><th>Net</th><th>Status</th></tr></thead><tbody>${orders.slice(0,4).map(o=>`<tr><td>Sep ${o.id==='ORD-1042'?'29':'28'}</td><td><div class="primary-cell"><strong>${esc(o.guest)}</strong><span>${esc(o.item)}</span></div></td><td>${o.payment}</td><td>${o.total}</td><td>₱${o.total==='₱1,200'?'120':'240'}</td><td class="amount">${o.total==='₱1,200'?'₱1,080':'₱2,160'}</td><td><span class="status ${o.settlement.toLowerCase().replaceAll(' ','-')}">${o.settlement}</span></td></tr>`).join('')}</tbody></table></div></section>`}
function profileView(){return `${head('Profile','Business details, team access, settlement terms, and support.')}<div class="profile-grid"><section class="card profile-card"><div class="card-header"><h2>Business details</h2><button class="button small" data-toast="Business details editor opened">Edit</button></div><div class="profile-body"><div class="profile-identity"><span class="profile-avatar">SB</span><div><strong>Sans Rival Bakehouse</strong><span>Bakery · Partner vendor</span></div></div><div class="settings-list"><div class="setting-row"><div><strong>Contact</strong><span>Leah Santos · +63 917 555 0182</span></div></div><div class="setting-row"><div><strong>Address</strong><span>South wing · Luna Bay Resort</span></div></div><div class="setting-row"><div><strong>Linked hotel</strong><span>Luna Bay Resort</span></div></div></div></div></section><section class="card profile-card"><div class="card-header"><h2>Verification documents</h2><span class="status confirmed">Verified</span></div><div class="profile-body"><div class="setting-row"><div><strong>Business permit</strong><span>Uploaded Sep 12 · Valid through 2027</span></div><button class="button small" data-toast="Document viewer opened">View</button></div><div class="setting-row"><div><strong>Owner ID</strong><span>Uploaded Sep 12 · Verified</span></div><button class="button small" data-toast="Document viewer opened">View</button></div></div></section><section class="card profile-card"><div class="card-header"><h2>Team accounts</h2><button class="button small" data-toast="Invite staff opened">Add staff</button></div><div class="profile-body"><div class="setting-row"><div><strong>Leah Santos</strong><span>Owner · Full access</span></div><span class="status confirmed">Active</span></div><div class="setting-row"><div><strong>Marco Dela Cruz</strong><span>Staff · Orders and Listings view</span></div><span class="status confirmed">Active</span></div></div></section><section class="card profile-card"><div class="card-header"><h2>Payout account</h2><button class="button small" data-toast="Payout account editor opened">Edit</button></div><div class="profile-body"><div class="setting-row"><div><strong>BDO · ending 2084</strong><span>Weekly settlement by default · Every Friday</span></div><span class="status confirmed">Verified</span></div><div class="setting-row"><div><strong>Notifications</strong><span>Push, SMS, and email for order updates</span></div><button class="toggle on" aria-label="Notifications enabled"></button></div><div class="profile-links"><button data-toast="Help center opened">Help & support ${icons.arrow}</button><button data-toast="Logged out">Log out ${icons.arrow}</button></div></div></section></div>`}
function view(){return state.page==='dashboard'?dashboard():state.page==='orders'?ordersView():state.page==='listings'?listingsView():state.page==='earnings'?earningsView():state.page==='profile'?profileView():dashboard()}
function render(){document.querySelector('#app').innerHTML=shell(view());bind()}
function toast(message){const node=document.createElement('div');node.className='toast';node.textContent=message;document.querySelector('#toast-region').append(node);setTimeout(()=>node.remove(),2600)}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.detail=null;render()});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{state.detail=b.dataset.detail;render()});document.querySelectorAll('[data-order-filter]').forEach(b=>b.onclick=()=>{state.orderFilter=b.dataset.orderFilter;render()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.orderView=b.dataset.view;render()});const search=document.querySelector('[data-search]');if(search){search.oninput=e=>{state.query=e.target.value;const pos=e.target.selectionStart;render();const next=document.querySelector('[data-search]');next.focus();next.setSelectionRange(pos,pos)}}document.querySelectorAll('[data-toast]').forEach(b=>b.onclick=()=>toast(b.dataset.toast));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const o=orders.find(x=>x.id===state.detail);const a=b.dataset.action;if(a==='confirm')o.status='Confirmed';if(a==='preparing')o.status='Preparing';if(a==='ready')o.status='Ready';if(a==='complete')o.status='Completed';if(a==='cancel'){o.status='Cancelled';toast('Cancellation recorded · refund policy shown to guest')}if(a==='reschedule')toast('Reschedule request opened');if(a!=='reschedule')toast(`Order ${o.id} updated`);render()});document.querySelectorAll('[data-listing-new]').forEach(b=>b.onclick=()=>toast('New listing form opened'))}
render();
